
import CryptoSaveForm from '@/Components/Forms/Backend/Crypto/CryptoSaveForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import {
    ArrowUpDown,
    Coins,
    RefreshCw,
    RotateCcw,
    TrendingDown,
    TrendingUp
} from 'lucide-react';
import z from 'zod';

export function useCryptoConfig(props: CrudPageProps): CrudConfig {
    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const advanceFilterOptions = props?.advanceFilterOptions || [];
    const routePrefix = modelProperty?.routePrefix;

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Crypto Currencies'), href: route(`${routePrefix}.index`) },
    ];

    return {
        formComponent: CryptoSaveForm,
        fetchToggle: true,

        customHeaderActions: [
            {
                key: 'attendances',
                label: t('Sync Crypto'),
                tooltip: t('Sync Price'),
                className: "h-9 rounded-lg",
                icon: RotateCcw,
                permission: 'crypto.create',
                href: route('backend.crypto-currencies.sync'),
            },
        ],

        form: {
            title: {
                create: t('Add Crypto Currency'),
                edit: t('Edit Crypto Currency'),
            },
            description: {
                create: t('Add a new cryptocurrency to the platform'),
                edit: t('Update cryptocurrency details'),
            },
            submitButtonText: {
                create: t('Add Currency'),
                edit: t('Update Currency'),
            },

            fields: [
                // ── Basic info ──────────────────────────────────────────────────────
                {
                    name: 'name',
                    label: t('Coin Name'),
                    type: 'text',
                    placeholder: t('e.g. Bitcoin'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('Full name of the cryptocurrency'),
                },
                {
                    name: 'symbol',
                    label: t('Symbol / Ticker'),
                    type: 'text',
                    placeholder: t('e.g. BTC'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('Trading symbol (will be uppercased automatically)'),
                },
                {
                    name: 'coingecko_id',
                    label: t('CoinGecko ID'),
                    type: 'text',
                    placeholder: t('e.g. bitcoin'),
                    required: false,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('Used to fetch live prices. Search below to find the correct ID.'),
                },
                {
                    name: 'binance_symbol',
                    label: t('Binance Trading Pair'),
                    type: 'text',
                    placeholder: t('e.g. BTCUSDT'),
                    required: false,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('Used for the TradingView chart on the trade page'),
                },
                {
                    name: 'status',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    options: [
                        { value: 'active', label: t('Active') },
                        { value: 'inactive', label: t('Inactive') },
                    ],
                    description: t('Only active coins are shown to users'),
                },



            ],
        },

        formValidationRules: {
            name: z.string().min(1, 'Coin name is required').max(100),
            symbol: z.string().min(1, 'Symbol is required').max(20),
            coingecko_id: z.string().optional(),
            binance_symbol: z.string().optional(),
            status: z.string().min(1, 'Status is required'),

        },

        resource: 'crypto',
        resourcePlural: 'cryptos',
        title: t('Crypto Currencies'),
        description: t('Manage platform cryptocurrencies and their settings'),

        routes: {
            index: `${routePrefix}.index`,
            create: `${routePrefix}.create`,
            store: `${routePrefix}.store`,
            destroy: `${routePrefix}.destroy`,
            bulkAction: `${routePrefix}.bulk.action`,
            updateStatus: `${routePrefix}.update.status`,
        },

        formDisplayMode: 'page',
        viewDisplayMode: 'page',
        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Crypto Currencies'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Add Currency'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Edit Currency'), href: null, active: true },
            ],
        },

        table: {
            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search by name or symbol…'),
            sortable: true,
            defaultSort: 'sort_order',
            defaultSortDirection: 'asc',
            emptyMessage: t('No cryptocurrencies added yet. Add your first coin to get started.'),
            emptyMessageIcon: Coins,

            dragdrop: true,
            dragdropRoute: `${routePrefix}.update.order`,


            bulkActions: [
                { key: 'active', permission: 'crypto.edit' },
                { key: 'inactive', permission: 'crypto.edit' },
            ],

            columns: [
                {
                    key: 'name',
                    label: t('Coin'),
                    sortable: false,
                    filterable: true,
                    priority: 0,
                    defaultIcon: Coins,

                    render: (row: any) => (

                        <div className="flex items-center gap-3 max-w-full">
                            {/* Avatar */}
                            <div className="flex-shrink-0 w-10 h-10">
                                {row.images?.small ? (
                                    <img
                                        src={row.images?.small}
                                        alt={row.name}
                                        className="w-10 h-10 object-cover rounded-full border"
                                    />
                                ) : (
                                    <div className="flex items-center justify-center w-10 h-10 rounded-full border bg-gray-100 dark:bg-gray-700">
                                        <Coins className="w-5 h-5 text-gray-400" />
                                    </div>
                                )}
                            </div>

                            {/* Text */}
                            <div className="flex-1 min-w-0">
                                <p
                                    className="text-sm font-medium text-gray-900 dark:text-gray-100
                          truncate leading-tight"
                                    title={row.name}
                                >
                                    {row.name}
                                </p>
                            </div>
                        </div>
                    )
                },
                {
                    key: 'symbol',
                    label: t('Symbol'),
                    sortable: false,
                    priority: 1,
                    render: (row: any) => (
                        <span className=" font-bold text-sm px-2 py-0.5 bg-muted rounded">
                            {row.symbol}
                        </span>
                    ),
                },
                {
                    key: 'usd_price',
                    label: t('Price (USD)'),
                    sortable: false,
                    priority: 1,
                    render: (row: any) => (
                        <div className="space-y-0.5">
                            <div className=" text-sm font-semibold">
                                {row.usd_price ? `$${Number(row.usd_price).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}` : '—'}
                            </div>
                            {row.price_change_24h !== null && row.price_change_24h !== undefined && (
                                <div className={`flex items-center gap-1 text-xs ${Number(row.price_change_24h) >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                                    {Number(row.price_change_24h) >= 0
                                        ? <TrendingUp className="w-3 h-3" />
                                        : <TrendingDown className="w-3 h-3" />
                                    }
                                    {Number(row.price_change_24h).toFixed(2)}%
                                </div>
                            )}
                        </div>
                    ),
                },
                {
                    key: 'coingecko_id',
                    label: t('CoinGecko ID'),
                    sortable: false,
                    priority: 2,
                    render: (row: any) => (
                        <span className=" text-xs text-muted-foreground">
                            {row.coingecko_id || '—'}
                        </span>
                    ),
                },
                {
                    key: 'price_updated_at',
                    label: t('Price Updated'),
                    sortable: false,
                    priority: 3,
                    render: (row: any) => (
                        <div className="flex items-center gap-1 text-xs text-muted-foreground">
                            <RefreshCw className="w-3 h-3" />
                            {row.price_updated_at
                                ? new Date(row.price_updated_at).toLocaleString()
                                : t('Never')
                            }
                        </div>
                    ),
                },
                {
                    key: 'sort_order',
                    label: t('Order'),
                    sortable: false,
                    priority: 4,
                    render: (row: any) => (
                        <div className="flex items-center gap-1 text-sm text-muted-foreground">
                            <ArrowUpDown className="w-3 h-3" />
                            {row.sort_order ?? 0}
                        </div>
                    ),
                },
                {
                    key: 'status',
                    label: t('Status'),
                    sortable: false,
                    priority: 3,
                    render: (row: any) => (
                        <div className="mt-1.5">
                            <StatusBadge status={row.status} />
                        </div>
                    ),
                },
            ],

        },


        filters: {
            searchFields: ['name', 'symbol'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                create: 'crypto.create',
                edit: 'crypto.edit',
                view: 'crypto.view',
                delete: 'crypto.delete',
            },
        },

        actionConstraints: {
            delete: [],
        },

        destroyDialogConfig: {
            title: t('Delete Cryptocurrency'),
            description: t('Are you sure you want to delete this cryptocurrency? This action cannot be undone.'),
            itemName: {
                label: t('Coin Name'),
                key: 'name',
                render: (name: string) => name,
            },
            itemType: 'Cryptocurrency',
            warningMessage: t('Deleting this coin will remove it from the platform and all associated wallet addresses.'),
            showWarningAlert: true,
            showItemDetails: true,

        },

        labels: {
            singular: 'Cryptocurrency',
            plural: 'Cryptocurrencies',
            key: 'crypto',
        },

        saveAlertInfo: {
            title: t('Cryptocurrency Configuration'),
            description: t('Fill in the details below. Set the CoinGecko ID to enable live price syncing.'),
        },
    };
}
